// Generated by AI
using System.Collections;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

public class SettingsPanel : MonoBehaviour
{
    [SerializeField] private List<TMP_Text> textsToScale; // All texts that change size with the setting
    [SerializeField] private TMP_Text captionText; // Text component where sound captions are shown
    [SerializeField] private Toggle captionsToggle; // Toggle that turns captions on or off

    private const string TextSizeKey = "TextSizeLevel"; // PlayerPrefs key for the text size
    private const string CaptionsKey = "CaptionsEnabled"; // PlayerPrefs key for the captions setting

    private readonly float[] sizeMultipliers = { 1f, 1.25f, 1.5f }; // Small, Medium and Large
    private readonly List<float> baseFontSizes = new List<float>(); // Original font size of each text
    private bool captionsEnabled = true; // Tracks if captions are currently allowed
    private Coroutine captionRoutine; // Reference to the running caption timer

    // Stores the original font sizes and hides the caption text
    private void Awake()
    {
        foreach (TMP_Text text in textsToScale)
        {
            baseFontSizes.Add(text != null ? text.fontSize : 0f);
        }

        if (captionText != null)
        {
            captionText.gameObject.SetActive(false);
        }
    }

    // Loads the saved settings and applies them
    private void Start()
    {
        ApplyTextSize(PlayerPrefs.GetInt(TextSizeKey, 0));
        captionsEnabled = PlayerPrefs.GetInt(CaptionsKey, 1) == 1;

        if (captionsToggle != null)
        {
            captionsToggle.SetIsOnWithoutNotify(captionsEnabled); // Updates the toggle without firing its event
        }
    }

    // Changes the text size: 0 = Small, 1 = Medium, 2 = Large
    public void SetTextSize(int level)
    {
        level = Mathf.Clamp(level, 0, sizeMultipliers.Length - 1);
        ApplyTextSize(level);
        PlayerPrefs.SetInt(TextSizeKey, level);
        PlayerPrefs.Save();
    }

    // Scales every registered text from its original size
    private void ApplyTextSize(int level)
    {
        level = Mathf.Clamp(level, 0, sizeMultipliers.Length - 1);

        for (int i = 0; i < textsToScale.Count; i++)
        {
            if (textsToScale[i] != null)
            {
                textsToScale[i].fontSize = baseFontSizes[i] * sizeMultipliers[level];
            }
        }
    }

    // Turns sound captions on or off and saves the choice
    public void SetCaptionsEnabled(bool enabled)
    {
        captionsEnabled = enabled;
        PlayerPrefs.SetInt(CaptionsKey, enabled ? 1 : 0);
        PlayerPrefs.Save();

        if (!enabled)
        {
            HideCaption();
        }
    }

    // Shows a caption for the given time, only if captions are enabled
    public void ShowCaption(string text, float seconds)
    {
        if (!captionsEnabled || captionText == null)
        {
            return;
        }

        if (captionRoutine != null)
        {
            StopCoroutine(captionRoutine);
        }

        captionRoutine = StartCoroutine(CaptionRoutine(text, seconds));
    }

    // Shows the caption and hides it after the time passes (ignores the game pause)
    private IEnumerator CaptionRoutine(string text, float seconds)
    {
        captionText.text = text;
        captionText.gameObject.SetActive(true);
        yield return new WaitForSecondsRealtime(seconds); // Realtime keeps working when timeScale = 0
        captionText.gameObject.SetActive(false);
        captionRoutine = null;
    }

    // Stops any caption and hides the text
    private void HideCaption()
    {
        if (captionRoutine != null)
        {
            StopCoroutine(captionRoutine);
            captionRoutine = null;
        }

        if (captionText != null)
        {
            captionText.gameObject.SetActive(false);
        }
    }
}